import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md"}'),t={name:"guide/how-it-works.md"};function i(r,e,l,p,d,c){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><p>Weeabooify is built on top of the <strong>LSPosed / Xposed</strong> framework and uses runtime hooking to modify Android&#39;s SystemUI and Framework processes.</p><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Weeabooify App (User Process)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │  Preferences via RemotePreferences (ContentProvider)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  SystemUI Process</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │  YukiHookAPI hooks</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Hooked Classes</span></span>
<span class="line"><span>  ├── ShadeHeaderController   → QS header styles &amp; images</span></span>
<span class="line"><span>  ├── KeyguardRootView        → Lockscreen overlays &amp; widgets</span></span>
<span class="line"><span>  ├── NotificationPanelViewController → Panel behavior</span></span>
<span class="line"><span>  └── ... (more SystemUI targets)</span></span></code></pre></div><h2 id="key-technology" tabindex="-1">Key Technology <a class="header-anchor" href="#key-technology" aria-label="Permalink to &quot;Key Technology&quot;">​</a></h2><ul><li><strong><a href="https://github.com/HighCapable/YukiHookAPI" target="_blank" rel="noreferrer">YukiHookAPI</a></strong> — Kotlin-first hook API built on top of Xposed, used for all SystemUI hooks</li><li><strong><a href="https://github.com/HighCapable/KavaRef" target="_blank" rel="noreferrer">KavaRef</a></strong> — Modernized Java reflection utilities for resolving internal Android classes</li><li><strong>RemotePreferences</strong> — Cross-process preference sharing from the app to the hook module running inside SystemUI</li><li><strong>Jetpack Compose</strong> — UI layer for both the app and injected lockscreen overlay views</li><li><strong>DataStore</strong> — Persistent preference storage on the app side</li></ul><h2 id="why-no-system-modifications" tabindex="-1">Why No System Modifications? <a class="header-anchor" href="#why-no-system-modifications" aria-label="Permalink to &quot;Why No System Modifications?&quot;">​</a></h2><p>Unlike Substratum or manual overlay methods, Weeabooify hooks into running processes at <strong>Zygote fork time</strong> via LSPosed. This means:</p><ul><li>No need to modify <code>/system</code> or flash overlays</li><li>Changes are applied live on reboot</li><li>Easy to remove — just disable the module and reboot</li></ul><h2 id="safe-mode" tabindex="-1">Safe Mode <a class="header-anchor" href="#safe-mode" aria-label="Permalink to &quot;Safe Mode&quot;">​</a></h2><p>If Weeabooify causes a crash loop, LSPosed&#39;s built-in safe mode will automatically detect repeated crashes and disable the module before the system becomes unbootable. You can also manually recover via:</p><ul><li>Android&#39;s built-in Safe Mode (volume down at boot)</li><li>Deleting <code>data/adb/modules/weeabooify/</code> via custom recovery</li></ul>`,12)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
